<?php
$gruposPermisos = [];
foreach ($permisos as $permiso) {
    $prefijo = explode('.', $permiso['clave'])[0];
    $grupo = [
        'personas' => 'Personas y comunidad',
        'alumnos' => 'Personas y comunidad',
        'apoderados' => 'Personas y comunidad',
        'fotochecks' => 'Personas y comunidad',
        'academico' => 'Académico y matrículas',
        'matriculas' => 'Académico y matrículas',
        'asistencia' => 'Asistencia',
        'horarios' => 'Asistencia',
        'incidencias' => 'Asistencia',
        'cobros' => 'Cobros escolares',
        'planilla' => 'Planilla',
        'usuarios' => 'Seguridad',
        'auditoria' => 'Seguridad',
        'configuracion' => 'Configuración',
        'reportes' => 'Reportes',
        'portal' => 'Portal de familia',
    ][$prefijo] ?? 'Otros';
    $gruposPermisos[$grupo][] = $permiso;
}
?>
<div class="mb-6 flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between"><div><p class="text-sm font-medium text-blue-600">Seguridad</p><h1 class="text-2xl font-bold">Roles y permisos</h1><p class="mt-1 text-sm text-slate-500">Cree roles y defina los accesos de cada uno por módulo.</p></div><div class="flex gap-2"><a href="index.php?url=usuarios" class="rounded-xl border px-4 py-2 text-sm font-semibold">Usuarios</a><button onclick="document.getElementById('modal-registrar-rol').classList.remove('hidden')" class="rounded-xl bg-blue-600 px-4 py-2 text-sm font-semibold text-white"><i class="bi bi-plus-lg"></i> Registrar rol</button><button onclick="document.getElementById('seccion-lista-roles').scrollIntoView({behavior:'smooth'})" class="rounded-xl border border-slate-300 bg-white px-4 py-2 text-sm font-semibold">Mostrar roles</button></div></div>
<section id="seccion-lista-roles" class="overflow-hidden rounded-2xl border bg-white"><div class="overflow-x-auto"><table data-datatable class="min-w-full text-sm"><thead class="bg-slate-50 text-left text-xs uppercase text-slate-500"><tr><th class="px-5 py-4">Rol</th><th class="px-5 py-4">Usuarios</th><th class="px-5 py-4">Permisos</th><th class="px-5 py-4">Estado</th><th class="no-sort px-5 py-4">Acciones</th></tr></thead><tbody id="lista-roles" class="divide-y"><?php foreach($roles as $r): ?><tr data-buscar="<?= htmlspecialchars(strtolower($r['nombre'].' '.$r['estado']),ENT_QUOTES) ?>"><td class="px-5 py-4 font-medium"><?= htmlspecialchars($r['nombre']) ?></td><td class="px-5 py-4"><?= $r['usuarios'] ?></td><td class="px-5 py-4"><?= $r['permisos'] ?></td><td class="px-5 py-4"><?= $r['estado'] ?></td><td class="px-5 py-4"><button class="text-sm font-semibold text-blue-600" data-id="<?= $r['id_rol'] ?>" data-nombre="<?= htmlspecialchars($r['nombre'],ENT_QUOTES) ?>" data-estado="<?= $r['estado'] ?>" data-permisos="<?= $r['ids_permisos'] ?>" onclick="configurarRol(this)">Gestionar permisos</button></td></tr><?php endforeach;?></tbody></table></div></section>

<div id="modal-registrar-rol" class="fixed inset-0 z-[60] hidden bg-slate-900/45 p-4"><div class="modal-rol-registro rounded-2xl bg-white p-6 shadow-2xl"><button type="button" data-modal-close class="modal-x" onclick="this.closest('[id^=modal-]').classList.add('hidden')"><i class="bi bi-x-lg"></i></button><h2 class="text-lg font-bold">Registrar rol</h2><p class="mt-1 text-sm text-slate-500">Después podrá asignar sus permisos desde “Gestionar permisos”.</p><form method="post" action="index.php?url=roles_guardar" class="mt-5 grid gap-4"><?= campoCsrf() ?><label class="form-label">Nombre del rol<input required name="nombre" class="form-input" placeholder="Ej. Responsable de biblioteca"></label><label class="form-label">Estado<select name="estado" class="form-input"><option>ACTIVO</option><option>INACTIVO</option></select></label><div class="modal-acciones"><button type="button" class="modal-cancelar" onclick="this.closest('[id^=modal-]').classList.add('hidden')">Cancelar</button><button class="rounded-xl bg-blue-600 px-4 py-2 text-sm font-semibold text-white">Registrar rol</button></div></form></div></div>

<div id="modal-rol" class="fixed inset-0 z-[60] hidden overflow-y-auto bg-slate-900/45 p-4"><div class="modal-rol-contenido rounded-2xl bg-white p-6"><button type="button" data-modal-close class="modal-x" onclick="this.closest('[id^=modal-]').classList.add('hidden')"><i class="bi bi-x-lg"></i></button><h2 id="titulo-rol" class="text-lg font-bold">Gestionar rol y permisos</h2><form method="post" action="index.php?url=roles_guardar" class="mt-4"><?= campoCsrf() ?><input id="rol-id" type="hidden" name="id_rol"><div class="grid gap-3 sm:grid-cols-2"><label class="form-label">Nombre<input id="rol-nombre" required name="nombre" class="form-input"></label><label class="form-label">Estado<select id="rol-estado" name="estado" class="form-input"><option>ACTIVO</option><option>INACTIVO</option></select></label></div><div class="mt-5 flex items-center justify-between"><p class="text-sm font-semibold">Permisos por módulo</p><input id="buscar-permisos" class="form-input mt-0 w-72 max-w-[55%]" placeholder="Buscar permiso"></div><div id="lista-permisos" class="mt-4 space-y-5"><?php foreach($gruposPermisos as $grupo=>$grupoPermisos): ?><section class="rounded-xl border border-slate-200 p-4"><h3 class="mb-3 text-sm font-bold text-blue-700"><?= htmlspecialchars($grupo) ?></h3><div class="permisos-grid"><?php foreach($grupoPermisos as $p): ?><label data-permiso="<?= htmlspecialchars(strtolower($p['clave'].' '.$p['descripcion']),ENT_QUOTES) ?>" class="flex gap-2 rounded-lg border p-3 text-sm"><input type="checkbox" name="permisos[]" value="<?= $p['id_permiso'] ?>"><span><b><?= htmlspecialchars($p['clave']) ?></b><small class="block text-slate-500"><?= htmlspecialchars($p['descripcion']) ?></small></span></label><?php endforeach;?></div></section><?php endforeach;?></div><div class="modal-acciones mt-5"><button type="button" class="modal-cancelar" onclick="this.closest('[id^=modal-]').classList.add('hidden')">Cancelar</button><button class="rounded-xl bg-blue-600 px-4 py-2 text-sm font-semibold text-white">Guardar cambios</button></div></form></div></div>
<script>document.getElementById('buscar-permisos').oninput=function(){let q=this.value.toLowerCase();document.querySelectorAll('[data-permiso]').forEach(x=>x.style.display=x.dataset.permiso.includes(q)?'':'none')};function configurarRol(b){let e=document.getElementById('modal-rol');e.classList.remove('hidden');let ids=b.dataset.permisos?b.dataset.permisos.split(','):[];document.getElementById('rol-id').value=b.dataset.id;document.getElementById('rol-nombre').value=b.dataset.nombre;document.getElementById('rol-estado').value=b.dataset.estado;document.querySelectorAll('[data-permiso] input').forEach(x=>x.checked=ids.includes(x.value));}</script>
